export const reviewRow=(n,patch={})=>({rowNumber:n,contractId:reviewId(n),legajo:String(5000+n),name:'PERSONA SINTÉTICA '+String(n).padStart(3,'0'),status:'active',startDate:'2010-01-01',endDate:null,agreementCode:'1',categoryCode:'0',organizationId:'10',sectorCode:'20',jurisdictionCode:null,activeContractsForPerson:1,...patch});
export function reviewRaw(count=57,patch={}){return {scope:{tenantId:TENANT,membershipId:MEMBER,bindingId:reviewId(9001),companyId:101},source:{coreVersionId:reviewId(9002),curatedVersionId:reviewId(9003),sourceBatchId:reviewId(9004),coreBaselineBatchId:reviewId(9005),curatedBaselineBatchId:reviewId(9006),sourceSha256:'a'.repeat(64),coreManifestSha256:'b'.repeat(64),curatedManifestSha256:'c'.repeat(64),publicationSha256:'d'.repeat(64),cutoff:'2026-09-10T15:17:30'},today:'2026-10-06',queriedAt:'2026-10-06T12:00:00Z',total:count,rows:Array.from({length:count},(_,i)=>reviewRow(i+1)),...patch};}
